// Calcula quando enviar o lembrete: 24 horas antes da consulta
const item = $input.first().json;
const scheduledAt = new Date(item.data.scheduled_at);

// Lembrete 24h antes
const reminderTime = new Date(scheduledAt.getTime() - 24 * 60 * 60 * 1000);
const now = new Date();

// Se já passou do horário do lembrete, envia agora
const sendAt = reminderTime > now ? reminderTime : now;

// Formata a data da consulta para exibição
const appointmentDate = scheduledAt.toLocaleDateString('pt-BR', {
  weekday: 'long', day: '2-digit', month: '2-digit', year: 'numeric',
  timeZone: 'America/Sao_Paulo'
});
const appointmentTime = scheduledAt.toLocaleTimeString('pt-BR', {
  hour: '2-digit', minute: '2-digit',
  timeZone: 'America/Sao_Paulo'
});

// Monta a mensagem de lembrete
const clientName = item.data.client_name ? item.data.client_name.split(' ')[0] : 'cliente';
let message = `Olá, ${clientName}! 😊\n\nPassando para lembrar da sua consulta:`;
message += `\n\n📅 *${appointmentDate}*`;
message += `\n⏰ *${appointmentTime}*`;

if (item.data.location_name) {
  message += `\n\n📍 *${item.data.location_name}*`;
  if (item.data.address) message += `\n${item.data.address}`;
  if (item.data.city) message += `, ${item.data.city}`;
}

if (item.data.modality === 'online') {
  message += `\n\n💻 *Consulta online* — o link será enviado em breve`;
}

if (item.data.confirmation_message) {
  message += `\n\n${item.data.confirmation_message}`;
} else {
  message += `\n\nQualquer dúvida, é só falar! Até lá! 🌿`;
}

return [{
  json: {
    ...item,
    sendAt: sendAt.toISOString(),
    reminderMessage: message,
    appointmentDate,
    appointmentTime
  }
}];
